SKIP_POOL = ('Far', '_mid', '_far', '_xfar', 'lampPool', 'propContactAO', 'trees_', 'trunks_', '_l1_', 'roofplants', 'hvac_', 'vents_', 'dish_', 'antenna_', 'flags')
protos = [p for p in man['protos'] if not any(s in p['name'] for s in SKIP_POOL)]
if 'proto' in STEPS:
    import_files([os.path.join(EXPORT, p['file']) for p in protos], ROOT + '/Props/_in', mesh_pipeline(True))
    for p in protos:
        src = f'{ROOT}/Props/_in/{p["name"]}/StaticMeshes/{p["name"]}'; dst = f'{ROOT}/Props/SM_{p["name"]}'
        if not EAL.does_asset_exist(src): log('MISSING proto', src); continue
        EAL.rename_asset(src, dst); sm = load(dst)
        if 'leaves' in p['name']:
            mi = at.create_asset('MI_' + p['name'], MAT + '/Inst', unreal.MaterialInstanceConstant, unreal.MaterialInstanceConstantFactoryNew())
            mel.set_material_instance_parent(mi, load(MAT + '/M_CityLeaves'))
            u = (p.get('mat') or {}).get('map')
            if u:
                rel = u.split('5202/', 1)[-1].replace('/', '_').rsplit('.', 1)[0]
                if EAL.does_asset_exist(f'{ROOT}/Textures/Maps/{rel}'): mel.set_material_instance_texture_parameter_value(mi, 'Map', load(f'{ROOT}/Textures/Maps/{rel}'))
            EAL.save_asset(mi.get_path_name())
        else:
            mi = mi_for({**p, 'proto': True})
        finish_mesh(sm, mi, False, nanite=True)
        EAL.save_asset(dst)
    EAL.delete_directory(ROOT + '/Props/_in')
    log('protos', len(protos))

# ------------------------------------------------------------------------------------------------ maps
def U(x, y, z): return unreal.Vector(x * 100.0, z * 100.0, y * 100.0)
def look_rot(p, t):
    d = unreal.Vector(t.x - p.x, t.y - p.y, t.z - p.z)
    yaw = math.degrees(math.atan2(d.y, d.x)); pitch = math.degrees(math.atan2(d.z, math.hypot(d.x, d.y)))
    return unreal.Rotator(roll=0.0, pitch=pitch, yaw=yaw)
eas = unreal.get_editor_subsystem(unreal.EditorActorSubsystem)
les = unreal.get_editor_subsystem(unreal.LevelEditorSubsystem)
def spawn(cls, loc=unreal.Vector(0, 0, 0), rot=unreal.Rotator(0, 0, 0), label=None, folder=None):
    a = eas.spawn_actor_from_class(cls, loc, rot)
    if label: a.set_actor_label(label)
    if folder: a.set_folder_path(folder)
    return a
sds = unreal.get_engine_subsystem(unreal.SubobjectDataSubsystem)
def add_component(actor, cls):
    root = sds.k2_gather_subobject_data_for_instance(actor)[0]
    h, fail = sds.add_new_subobject(unreal.AddNewSubobjectParams(parent_handle=root, new_class=cls, blueprint_context=None))
    return unreal.SubobjectDataBlueprintFunctionLibrary.get_object(unreal.SubobjectDataBlueprintFunctionLibrary.get_data(h))

SHOTS = json.load(open(os.path.join(os.path.dirname(os.path.abspath(__file__)) if '__file__' in globals() and os.path.exists(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'city_shots.json')) else '/Users/midir/sm2-n1/city/unreal/WebHomage/Scripts', 'city_shots.json')))

def open_level(path):
    """idempotent: an existing map is opened and emptied (deleting maps pops a modal dialog), else created"""
    if EAL.does_asset_exist(path):
        unreal.EditorLoadingAndSavingUtils.load_map(path)
        for a in eas.get_all_level_actors():
            if a.get_class().get_name() not in ('WorldSettings', 'Brush', 'DefaultPhysicsVolume', 'GameplayDebuggerCategoryReplicator', 'WorldDataLayers', 'WorldPartitionMiniMap'):
                eas.destroy_actor(a)
    else:
        les.new_level(path)
    return unreal.get_editor_subsystem(unreal.UnrealEditorSubsystem).get_editor_world()

def build_geo_level(path):
    open_level(path)
    recs = [r for r in man['meshes'] if keep_mesh(r)]
    for r in recs:
        base = os.path.basename(r['file'])[:-4]; sp = f'{ROOT}/Meshes/{r["kind"]}/SM_{base}'
        if not EAL.does_asset_exist(sp): continue
        a = spawn(unreal.StaticMeshActor, U(r['center'][0], 0, r['center'][2]), label=base, folder='City/' + r['kind'])
        smc = a.static_mesh_component; smc.set_static_mesh(load(sp))
        a.set_mobility(unreal.ComponentMobility.STATIC)
    # instanced props / trees from layout.json pool items
    L = json.load(open(os.path.join(EXPORT, 'layout.json')))
    ni = 0
    for p in protos:
        pool = p['src']; items = (L['instances'].get(pool) or {}).get('items') or []
        sp = f'{ROOT}/Props/SM_{p["name"]}'
        if not items or not EAL.does_asset_exist(sp): continue
        a = spawn(unreal.Actor, unreal.Vector(0, 0, 0), label='ISM_' + p['name'], folder='City/Props')
        c = add_component(a, unreal.HierarchicalInstancedStaticMeshComponent)
        c.set_static_mesh(load(sp)); c.set_editor_property('num_custom_data_floats', 4)
        xs = []
        for it in items:
            s = it.get('s', 1.0); s3 = it.get('s3') or [1, 1, 1]
            # browser: rotation about +y by ry (right-handed, y up). UE: yaw about Z with Y = z mirrored handedness -> yaw = -ry
            rot = unreal.Rotator(roll=math.degrees(it.get('rz', 0.0)), pitch=-math.degrees(it.get('rx', 0.0)), yaw=-math.degrees(it.get('ry', 0.0)))
            xs.append(unreal.Transform(U(it['x'], it['y'], it['z']), rot, unreal.Vector(s * s3[0], s * s3[2], s * s3[1])))
        ids = c.add_instances(xs, True, True)
        for k, it in enumerate(items):
            tint = ((it.get('e') or {}).get('aTint')) or [1, 1, 1]; st = (it.get('e') or {}).get('aState', 0)
            for j, v in enumerate((tint[0], tint[1], tint[2], st if isinstance(st, (int, float)) else 0)): c.set_custom_data_value(k, j, float(v), False)
        ni += len(items)
    # ground under everything (lot interiors / plazas never exported as geometry)
    g = spawn(unreal.StaticMeshActor, U(128, -0.08, -128), label='GroundPlane', folder='City')
    g.static_mesh_component.set_static_mesh(load('/Engine/BasicShapes/Plane')); g.set_actor_scale3d(unreal.Vector(80, 80, 1))
    g.static_mesh_component.set_material(0, load(MAT + '/M_CityAsphalt'))
    les.save_current_level()
    log('geo level', path, len(recs), 'meshes', ni, 'instances')

def add_lighting(sun_pitch, sun_yaw, sunset=False):
    sun = spawn(unreal.DirectionalLight, unreal.Vector(0, 0, 50000), unreal.Rotator(roll=0, pitch=sun_pitch, yaw=sun_yaw), 'Sun', 'Lighting')
    lc = sun.light_component
    lc.set_editor_property('intensity', 6.0 if not sunset else 4.0)
    lc.set_editor_property('atmosphere_sun_light', True); lc.set_mobility(unreal.ComponentMobility.MOVABLE)
    spawn(unreal.SkyAtmosphere, unreal.Vector(0, 0, 0), label='SkyAtmosphere', folder='Lighting')
    sl = spawn(unreal.SkyLight, unreal.Vector(0, 0, 2000), label='SkyLight', folder='Lighting')
    sl.light_component.set_editor_property('real_time_capture', True); sl.light_component.set_mobility(unreal.ComponentMobility.MOVABLE)
    fog = spawn(unreal.ExponentialHeightFog, unreal.Vector(0, 0, 0), label='HeightFog', folder='Lighting')
    fc = fog.component; fc.set_editor_property('fog_density', 0.0025 if not sunset else 0.004); fc.set_editor_property('fog_height_falloff', 0.2)
    spawn(unreal.VolumetricCloud, unreal.Vector(0, 0, 0), label='Clouds', folder='Lighting')
    ppv = spawn(unreal.PostProcessVolume, unreal.Vector(0, 0, 0), label='PPV', folder='Lighting')
    ppv.set_editor_property('unbound', True)
    st = ppv.get_editor_property('settings')  # simple, deterministic exposure for the city test maps (P4 owns the final look)
    for k, v in (('auto_exposure_method', unreal.AutoExposureMethod.AEM_MANUAL), ('auto_exposure_bias', 2.0 if not sunset else 2.3),
                 ('auto_exposure_apply_physical_camera_exposure', False)):
        st.set_editor_property('override_' + k, True); st.set_editor_property(k, v)
    ppv.set_editor_property('settings', st)

if 'map' in STEPS:
    unreal.EditorAssetLibrary.make_directory(TESTS)
    build_geo_level(TESTS + '/City_Midtown_Geo')
    # playable test map: geometry (streamed, always loaded) + day light + PlayerStart on the 5th-Avenue-like crosswalk
    for mp, sun, cam in [('City_Midtown', (-42, 135), None)] + [(f'City_View_{s["id"]}', tuple(s.get('sun', (-42, 135))), s) for s in SHOTS]:
        world = open_level(f'{TESTS}/{mp}')
        if not any('City_Midtown_Geo' in l.get_path_name() for l in unreal.EditorLevelUtils.get_levels(world)):
            unreal.EditorLevelUtils.add_level_to_world(world, TESTS + '/City_Midtown_Geo', unreal.LevelStreamingAlwaysLoaded)
        if not les.set_current_level_by_name(mp): log('WARN could not make persistent level current', mp)  # new actors go to the persistent level, not the streamed geometry
        add_lighting(sun[0], sun[1], sunset=bool(cam and cam.get('sunset')))
        ps = SHOTS[0]['player'] if cam is None else cam.get('player', SHOTS[0]['player'])
        spawn(unreal.PlayerStart, U(ps[0], ps[1] + 1.0, ps[2]), unreal.Rotator(0, 0, -90), 'PlayerStart')
        if cam:
            p, t = U(*cam['pos']), U(*cam['target'])
            ca = spawn(unreal.CameraActor, p, look_rot(p, t), 'ShotCam_' + cam['id'])
            ca.camera_component.set_editor_property('field_of_view', cam.get('fov', 70))
            ca.camera_component.set_editor_property('constrain_aspect_ratio', False)
            ca.set_editor_property('auto_activate_for_player', unreal.AutoReceiveInput.PLAYER0)
        unreal.EditorLoadingAndSavingUtils.save_map(world, f'{TESTS}/{mp}')
        log('map', mp)
log('DONE')
